package com.phoenix.business.service;import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import lombok.RequiredArgsConstructor;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;import java.io.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class ReportService {private final MemberRepository members;private final PaymentRepository payments;private final BusinessSettingsRepository settings;public byte[] members()throws IOException{return workbook("Members Report",List.of("Member ID","Name","Phone","Email","Status","Expiry"),members.findAll().stream().map(m->List.of(n(m.getMemberCode()),n(m.getName()),n(m.getPhone()),n(m.getEmail()),n(m.getStatus()),n(m.getExpiryDate()))).toList());}public byte[] payments()throws IOException{return workbook("Payments Report",List.of("Receipt","Member","Plan","Date","Amount","Method","Status"),payments.findAll().stream().map(p->List.of(n(p.getReceiptNumber()),n(p.getMember().getName()),n(p.getPlanNameSnapshot()),n(p.getPaymentDate()),n(p.getAmount()),n(p.getMethod()),n(p.getStatus()))).toList());}private String n(Object o){return o==null?"":String.valueOf(o);}private byte[] workbook(String title,List<String> heads,List<List<String>> rows)throws IOException{try(Workbook w=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet s=w.createSheet(title);CellStyle h=w.createCellStyle();Font f=w.createFont();f.setBold(true);h.setFont(f);String gym=settings.findById(1L).map(BusinessSettings::getGymName).orElse("Phoenix Gym");Row meta=s.createRow(0);meta.createCell(0).setCellValue(gym+" — "+title+" — generated "+Instant.now());Row hr=s.createRow(2);for(int i=0;i<heads.size();i++){Cell c=hr.createCell(i);c.setCellValue(heads.get(i));c.setCellStyle(h);}int r=3;for(List<String> row:rows){Row x=s.createRow(r++);for(int i=0;i<row.size();i++)x.createCell(i).setCellValue(row.get(i));}s.createFreezePane(0,3);s.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(2,Math.max(2,r-1),0,heads.size()-1));for(int i=0;i<heads.size();i++){s.autoSizeColumn(i);s.setColumnWidth(i,Math.min(16000,s.getColumnWidth(i)+800));}w.write(out);return out.toByteArray();}}}
